css:
.pod-root * { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }
.pod-root { font-family: 'Pretendard', sans-serif; background: var(--pn-060e14, #060e14); color: var(--pn-f8fafc, #f8fafc); min-height: 100vh; padding: 32px 16px; display: flex; flex-direction: column; align-items: center; }
.pod-root .pod-container { width: 100%; max-width: 900px; }
.pod-root .pod-header { text-align: center; margin-bottom: 28px; }
.pod-root .pod-badge { display: inline-flex; align-items: center; gap: 6px; padding: 5px 12px; background: rgba(var(--pod-accent-rgb, 16,185,129), 0.15); border: 1px solid rgba(var(--pod-accent-rgb, 16,185,129), 0.4); border-radius: 9999px; font-size: 12px; font-weight: 800; color: var(--pod-accent, #34d399); margin-bottom: 12px; }
.pod-root .pod-title { font-size: 26px; font-weight: 900; letter-spacing: -0.02em; color: var(--pn-ffffff, #fff); margin-bottom: 8px; }
.pod-root .pod-desc { font-size: 14px; color: var(--pt-94a3b8, #94a3b8); }

.pod-root .calc-card { background: var(--pn-0f1c24, #0f1c24); border: 1px solid var(--pn-ffffff-008, rgba(255,255,255,0.08)); border-radius: 28px; padding: 36px 32px; box-shadow: 0 20px 40px var(--pn-000000-05, rgba(0,0,0,0.5)); margin-bottom: 24px; }
.pod-root .grid-2col { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; }
@media (max-width: 768px) { .pod-root .grid-2col { grid-template-columns: 1fr; } .pod-root .calc-card { padding: 24px 20px; } }

.pod-root .input-group { margin-bottom: 18px; }
.pod-root .input-label { font-size: 13px; font-weight: 700; color: var(--pt-94a3b8, #94a3b8); margin-bottom: 6px; display: block; }
.pod-root .input-field { width: 100%; padding: 13px 16px; background: var(--pn-ffffff-004, rgba(255,255,255,0.04)); border: 1.5px solid var(--pn-ffffff-01, rgba(255,255,255,0.1)); border-radius: 12px; color: var(--pn-ffffff, #fff); font-size: 15px; font-weight: 700; outline: none; }
.pod-root .input-field:focus { border-color: var(--pod-accent, #10b981); }

/* Comparison Box */
.pod-root .compare-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-top: 10px; }
.pod-root .compare-card { background: var(--pn-000000-03, rgba(0,0,0,0.3)); border: 1px solid var(--pn-ffffff-008, rgba(255,255,255,0.08)); border-radius: 18px; padding: 20px 16px; text-align: center; }
.pod-root .compare-card.highlight { border-color: var(--pod-accent, #10b981); background: rgba(var(--pod-accent-rgb, 16,185,129), 0.08); }
.pod-root .compare-name { font-size: 13px; font-weight: 800; color: var(--pt-94a3b8, #94a3b8); margin-bottom: 6px; }
.pod-root .compare-margin { font-size: 32px; font-weight: 900; color: var(--pn-ffffff, #fff); letter-spacing: -0.02em; margin-bottom: 4px; }
.pod-root .compare-profit { font-size: 13px; font-weight: 700; color: var(--pod-accent, #34d399); }

.pod-root .alert-box { background: rgba(239,68,68,0.1); border-left: 4px solid #ef4444; border-radius: 12px; padding: 14px 16px; font-size: 12.5px; color: var(--pt-fca5a5, #fca5a5); margin-top: 18px; line-height: 1.5; }
.pod-root .btn-magnet { width: 100%; padding: 15px; background: var(--pod-accent, #10b981); border: none; border-radius: 14px; font-size: 14px; font-weight: 900; color: #000; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 20px; transition: all 0.2s; }
.pod-root .btn-magnet:hover { background: var(--pod-accent, #34d399); transform: translateY(-1px); }
.pod-root{min-height:0;width:100%;max-width:100%;overflow-x:hidden;}

