function calculateMargin() {
      var sale = parseFloat(document.getElementById('inpSalePrice').value) || 0;
      var cost = parseFloat(document.getElementById('inpCostPrice').value) || 0;
      var delivery = parseFloat(document.getElementById('inpDelivery').value) || 0;
      var catFeeRate = (parseFloat(document.getElementById('inpCategoryFee').value) || 0) / 100;

      // 1. 스마트스토어 (수수료 약 5.63% + 배송비)
      var naverFee = sale * 0.0563;
      var naverProfit = sale - cost - delivery - naverFee;
      var naverRate = sale > 0 ? ((naverProfit / sale) * 100).toFixed(1) : 0;

      // 2. 쿠팡 로켓그로스 (카테고리 수수료 + 입출고/보관료 약 2,600원 + 부가세)
      var coupangFee = sale * catFeeRate;
      var fulfillmentFee = 2650; // 표준 소형 로켓그로스 피
      var coupangProfit = sale - cost - coupangFee - fulfillmentFee;
      var coupangRate = sale > 0 ? ((coupangProfit / sale) * 100).toFixed(1) : 0;

      document.getElementById('naverMargin').innerText = naverRate + '%';
      document.getElementById('naverProfit').innerText = (naverProfit >= 0 ? '+' : '') + Math.round(naverProfit).toLocaleString() + '원';

      var cpMarginEl = document.getElementById('coupangMargin');
      var cpProfitEl = document.getElementById('coupangProfit');
      cpMarginEl.innerText = coupangRate + '%';
      cpProfitEl.innerText = (coupangProfit >= 0 ? '+' : '') + Math.round(coupangProfit).toLocaleString() + '원';

      if (coupangProfit < 0) {
        cpMarginEl.style.color = 'var(--pt-ef4444, #ef4444)';
        cpProfitEl.style.color = 'var(--pt-ef4444, #ef4444)';
        document.getElementById('warningBox').innerHTML = '🚨 <strong>역마진 발생!</strong> 판매할수록 손실이 발생합니다. 판매가를 높이거나 매입 원가를 재조정하세요.';
      } else {
        cpMarginEl.style.color = '#f59e0b';
        cpProfitEl.style.color = '#f59e0b';
        document.getElementById('warningBox').innerHTML = '💡 <strong>주의:</strong> 로켓그로스는 풀필먼트 수수료가 추가 차감됩니다. 광고비(ROAS) 집행 시 신중한 마진 관리가 필요합니다.';
      }
    }

    document.querySelectorAll('.input-field').forEach(function(inp) {
      inp.addEventListener('input', calculateMargin);
    });

    calculateMargin();
    if (window.lucide) lucide.createIcons();

    if (window.MazaTelemetry) {
      window.MazaTelemetry.init({ podId: 'margin' });
    }
